mapper.update:
UPDATE order_return_check SET check_status=#{status},checked_at=IF(#{status}='no_issue',#{at},NULL),closed_at=#{at},closed_by_user_id=#{actor},
    operator_user_id=IF(#{status}='no_issue',#{actor},operator_user_id),close_reason_code=#{reasonCode},close_reason=#{reason},version=version+1,updated_at=#{at}
    WHERE id=#{id} AND version=#{version} AND check_status IN ('warning','pending') AND claim_created=0 AND closed_at IS NULL

mapper.select:
SELECT s.id,s.rental_order_item_id item_id,s.prop_sn_id sn_id,n.sn_code,s.prop_qr_code_id qr_id,s.scanned_at
    FROM order_return_scan_record s JOIN order_return_check c ON c.id=s.return_check_id JOIN prop_sn_instance n ON n.id=s.prop_sn_id WHERE c.rental_order_id=#{orderId}
    ORDER BY s.scanned_at DESC,s.id DESC LIMIT #{query.pageSize} OFFSET #{query.offset}
